@@ -0,0 +1,38 @@
+package com.acme.billing.internal.tax;
+
+import com.acme.billing.api.TaxProvider;
+import com.acme.billing.api.TaxQuote;
+import java.io.IOException;
+import java.math.BigDecimal;
+import java.net.URI;
+import java.net.http.HttpClient;
+import java.net.http.HttpRequest;
+import java.net.http.HttpResponse;
+import java.net.URLEncoder;
+import java.nio.charset.StandardCharsets;
+import java.time.Duration;
+
+public final class HttpTaxProvider implements TaxProvider {
+    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
+    private final URI endpoint = URI.create(System.getProperty("billing.tax.endpoint", "http://tax.internal:8080/rate"));
+
+    @Override
+    public String name() {
+        return "http";
+    }
+
+    @Override
+    public TaxQuote quote(String country, BigDecimal net) throws IOException, InterruptedException {
+        String query = "?country=" + URLEncoder.encode(country, StandardCharsets.UTF_8);
+        HttpRequest req = HttpRequest.newBuilder(URI.create(endpoint + query))
+            .timeout(Duration.ofSeconds(3))
+            .GET()
+            .build();
+        HttpResponse<String> res = client.send(req, HttpResponse.BodyHandlers.ofString());
+        if (res.statusCode() != 200) {
+            throw new IOException("tax service returned " + res.statusCode());
+        }
+        BigDecimal rate = new BigDecimal(res.body().trim());
+        return new TaxQuote(country, rate, net.multiply(rate));
+    }
+}

