diff --git a/shipping/src/events/pipeline.ts b/shipping/src/events/pipeline.ts
new file mode 100644
--- /dev/null
+++ b/shipping/src/events/pipeline.ts
@@ -0,0 +1,40 @@
+export interface Stage<TIn, TOut, TCtx> {
+  name: string;
+  run(input: TIn, ctx: TCtx): Promise<TOut>;
+}
+
+export interface PipelineHooks<TCtx> {
+  beforeStage?: (name: string, ctx: TCtx) => void | Promise<void>;
+  afterStage?: (name: string, ctx: TCtx) => void | Promise<void>;
+  onError?: (name: string, err: unknown, ctx: TCtx) => void | Promise<void>;
+}
+
+export class Pipeline<TIn, TOut, TCtx extends object = Record<string, unknown>> {
+  private readonly stages: Array<Stage<any, any, TCtx>> = [];
+
+  constructor(private readonly hooks: PipelineHooks<TCtx> = {}) {}
+
+  static create<TIn, TCtx extends object = Record<string, unknown>>(hooks?: PipelineHooks<TCtx>): Pipeline<TIn, TIn, TCtx> {
+    return new Pipeline<TIn, TIn, TCtx>(hooks);
+  }
+
+  pipe<TNext>(stage: Stage<TOut, TNext, TCtx>): Pipeline<TIn, TNext, TCtx> {
+    this.stages.push(stage);
+    return this as unknown as Pipeline<TIn, TNext, TCtx>;
+  }
+
+  async execute(input: TIn, ctx: TCtx): Promise<TOut> {
+    let value: unknown = input;
+    for (const stage of this.stages) {
+      await this.hooks.beforeStage?.(stage.name, ctx);
+      try {
+        value = await stage.run(value, ctx);
+      } catch (err) {
+        await this.hooks.onError?.(stage.name, err, ctx);
+        throw err;
+      }
+      await this.hooks.afterStage?.(stage.name, ctx);
+    }
+    return value as TOut;
+  }
+}
